8c4a6d43	{"nickname": "明月", "name": "", "gender": "", "phone": "", "wechat": "", "age": "", "referrer": "耀凯", "referrer_handler": "", "member_type": "", "paid_content": [], "visit_count": 0, "core_situation": "", "need_tags": "", "follow_up_node": "", "follow_up_action": "", "positions": [], "self_tags": [], "work_status": "", "work_description": "", "basic_info": "", "assessment": "", "tags": "5.29加的 被主题吸引来的 时间都空的 说自己对人都是感兴趣的", "traffic_source": "", "traffic_source_detail": "", "tracking_plan": "", "id": "8c4a6d43", "created_at": "2026-06-10T17:58:32.206999Z", "updated_at": "2026-06-10T17:58:58.381660Z", "is_deleted": false, "deleted_at": null}
93ca656f	{"nickname": "语真", "name": "", "gender": "", "phone": "", "wechat": "", "age": "", "referrer": "阿翁", "referrer_handler": "", "member_type": "", "paid_content": [], "visit_count": 0, "core_situation": "", "need_tags": "", "follow_up_node": "", "follow_up_action": "", "positions": [], "self_tags": [], "work_status": "", "work_description": "", "basic_info": "", "assessment": "", "tags": "阿翁朋友，有一定信任度，费用已告知，目前全职宝妈，女儿上托班，独自带，老公共情能力差，有婆媳问题", "traffic_source": "", "traffic_source_detail": "", "tracking_plan": "", "id": "93ca656f", "created_at": "2026-06-10T17:58:23.191718Z", "updated_at": "2026-06-10T17:59:06.152191Z", "is_deleted": false, "deleted_at": null}
25f8fbb4	{"nickname": "晨晨", "name": "", "gender": "", "phone": "", "wechat": "", "age": "", "referrer": "耀凯", "referrer_handler": "", "member_type": "", "paid_content": [], "visit_count": 0, "core_situation": "", "need_tags": "", "follow_up_node": "", "follow_up_action": "", "positions": [], "self_tags": [], "work_status": "", "work_description": "", "basic_info": "", "assessment": "", "tags": "6.1小红书对活动感兴趣，感觉挺活泼的。参加过家排的沙龙感觉神奇蛮有意思的，认为自我探索是非常有趣的事情，朋友圈看是做家庭教育讲师的", "traffic_source": "", "traffic_source_detail": "", "tracking_plan": "", "id": "25f8fbb4", "created_at": "2026-06-10T17:58:49.087948Z", "updated_at": "2026-06-10T17:58:49.087948Z", "is_deleted": false, "deleted_at": null}
